{
  "name": "opencode-strip-empty-params-plugin",
  "version": "0.1.1",
  "description": "Strips empty-string values from non-required MCP tool-call arguments before the call reaches the server. Fixes LLM function-calling quirks where models emit every optional key with an empty default.",
  "license": "MIT",
  "type": "module",
  "main": "index.js",
  "files": [
    "index.js",
    "index.ts"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "mcp",
    "tool-call",
    "function-calling"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/EmilioEsposito/opencode-strip-empty-params-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/EmilioEsposito/opencode-strip-empty-params-plugin/issues"
  },
  "homepage": "https://github.com/EmilioEsposito/opencode-strip-empty-params-plugin#readme",
  "author": "Emilio Esposito",
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  }
}
